#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
#
# Bash parses the whole file before the first prompt, so wrapping all stages in
# a function means an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPLICATE=$HERE/replicate.sh
CONFIG=$HOME/.config
PART=${1:-}

if [[ "$(hostname)" == company-app-vps ]]; then
  warn "This is the prod VPS. The wizard is for the new box."
  exit 3
fi

case "$PART" in
cloud)
TOTAL_STAGES=3
banner "New company_app box, part 1 of 2: Oracle Cloud"

stage "Create the VM"
say "Sign in to the account that will own the box (dad's, on the free tier)."
open_url "https://cloud.oracle.com/compute/instances/create"
step "Name it. Do not use company-app-vps, the tools treat that name as prod."
step "Image: Canonical Ubuntu 24.04. Shape: VM.Standard.A1.Flex, 2 OCPU, 12 GB."
step "Boot volume: 50 GB. Add your SSH public key. Assign a public IPv4."
note "Prod's region is ap-singapore-2. Free-tier A1 capacity varies, so a retry may be needed."
pause "Press Enter once the VM is running"

stage "Attach the 150 GB volume"
open_url "https://cloud.oracle.com/block-storage/volumes"
step "Create a block volume of 150 GB in the VM's availability domain."
step "Open the VM, Attached block volumes, Attach. Choose paravirtualized."
warn "Leave it blank. replicate.sh formats only a blank disk, and only if there is exactly one."
pause "Press Enter once it is attached"

stage "Open only what the app needs"
say "Oracle's firewall is the outer wall. Docker's published ports skip ufw."
step "VM, Networking, the subnet, Security, the security list."
step "Allow ingress from 0.0.0.0/0: TCP 80, TCP 443, UDP 443, UDP 41641."
step "Keep TCP 22 until Tailscale works, then remove it."
warn "Do not open 8000, 8080, 6001 or 6002. Coolify is reached over Tailscale."
note "Menu names may differ a little in your console; the rules are what matter."
say ""
say "Next: ssh ubuntu@<public-ip>, clone the repo to ~/Projects/company_app, then:"
say "  sudo apt-get update && tools/replicate/replicate.sh apply"
say "It stops at anything that needs you. When it does:"
say "  tools/replicate/wizard.sh box"
;;

box)
TOTAL_STAGES=10
banner "New company_app box, part 2 of 2: on the box"

stage "Tailscale"
command -v tailscale >/dev/null || { warn "Run replicate.sh apply first, it installs Tailscale."; exit 1; }
say "This opens a login link. Use the tailnet that holds your other devices."
sudo tailscale up
tailscale ip -4 | head -1
say "From now on, SSH to that address. Then rerun: tools/replicate/replicate.sh apply"
pause "Press Enter once apply has finished and Coolify is running"

stage "Coolify account"
TS=$(tailscale ip -4 | head -1)
open_url "http://$TS:8000"
step "Create the first account right away. The first visitor becomes the admin."
step "Settings, Advanced: turn on API Access. Turn off registration."
step "Keys & Tokens, API Tokens: description deploy-gate, tick write and deploy, Create."
ENV_FILE="$CONFIG/company-app-deploy.env"
ask_secret COOLIFY_TOKEN "Paste the token (hidden):"
write_env COOLIFY_URL "http://localhost:8000"
pause "Press Enter to go on"

stage "Postgres"
say "In Coolify, create a project, then a PostgreSQL 18 database."
step "Image postgres:18-alpine. Database company_app. Leave Make it publicly available off."
step "Persistent storage, add a directory mount: source /mnt/data/pg-telemetry, destination /mnt/telemetry."
step "Custom PostgreSQL configuration, these three lines:"
say  "     listen_addresses = '*'"
say  "     shared_preload_libraries = 'pg_stat_statements'"
say  "     pg_stat_statements.track = all"
step "Start it. Copy its name as the app's DB_HOST below."
note "These labels come from Coolify's data on prod, the screens were not walked through. Follow the meaning."
pause "Press Enter once it is running"
DB=$(docker exec coolify-db psql -U coolify -d coolify -Atc "select uuid from standalone_postgresqls order by id limit 1")
docker exec "$DB" sh -c 'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Atc "select 1 from pg_tablespace where spcname = '"'"'telemetry'"'"'"' | grep -q 1 ||
  docker exec "$DB" sh -c "psql -U \"\$POSTGRES_USER\" -d \"\$POSTGRES_DB\" -c \"CREATE TABLESPACE telemetry LOCATION '/mnt/telemetry'\""
say "${GREEN}Telemetry tablespace is ready.${RESET} It must exist before the first deploy so V4 uses it."
ENV_FILE="$CONFIG/company-app-probe.env"
write_env PROBE_DB_CONTAINER "$DB"
pause "Press Enter to go on"

stage "The app"
say "In Coolify, add a resource in the same project."
step "Connect the private repo jsongalvez/company_app through a GitHub App, branch master."
step "Build pack Dockerfile, file /backend/Dockerfile, base directory /, port 3023."
step "Turn off auto deploy: the deploy gate does that once GitHub is green."
step "Domains: leave them for the DNS stage."
step "Environment variables, runtime only, none as build variables:"
say  "     APP_HOST APP_PORT DB_HOST DB_PORT POSTGRES_DB POSTGRES_USER POSTGRES_PASSWORD"
say  "     JWT_ISSUER JWT_AUDIENCE NTFY_URL NTFY_TOPIC SENTRY_DSN"
say  "     SMTP_HOST SMTP_PORT SMTP_USERNAME SMTP_PASSWORD SMTP_FROM"
step "Copy non-secret values from prod's Coolify page. POSTGRES_* come from the new database."
step "JWT_SECRET and AUTH_DUMMY_PASSWORD: new values, one line each from this:"
say  "     openssl rand -base64 48 | tr -d '\\n'; echo"
warn "Do not reuse prod's JWT_SECRET. A token signed on one box would sign in on the other."
pause "Press Enter once the variables are saved, do not deploy yet"
ENV_FILE="$CONFIG/company-app-deploy.env"
write_env COOLIFY_APP_UUID "$(docker exec coolify-db psql -U coolify -d coolify -Atc "select uuid from applications order by id limit 1")"

stage "Proxy"
TS=$(tailscale ip -4 | head -1)
open_url "http://$TS:8000/server"
step "Your server, Proxy, Configuration. Under the ports add: - '443:443/udp'"
step "Under command add these two lines:"
say  "     - '--entrypoints.https.http3'"
say  "     - '--entrypoints.https.transport.respondingTimeouts.idleTimeout=90s'"
step "Save, then Restart Proxy."
pause "Press Enter once it is back"

stage "DNS"
say "Pick the name. kiel.party is prod: moving it moves real users."
step "In Cloudflare, add A records for the new name to the box's public IP, proxy off."
step "In Coolify, set the app's domains, for example https://app.<name>,https://api.<name>."
step "Deploy. Certificates come from Let's Encrypt over port 80."
open_url "https://dash.cloudflare.com"
pause "Press Enter once the app shows healthy"

stage "Backups"
say "Give this box its own bucket. A shared one mixes two databases' nightly dumps."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "R2: create a bucket and an API token scoped to it, Object Read and Write."
ENV_FILE="$CONFIG/company-app-backup.env"
ask R2_ACCOUNT_ID "Cloudflare account id:"
ask R2_BUCKET "Bucket name:"
ask R2_ACCESS_KEY_ID "Access key id:"
ask_secret R2_SECRET_ACCESS_KEY "Secret access key (hidden):"
ask_secret BACKUP_PASSPHRASE "Passphrase for this box's backups (hidden):"
warn "Keep the passphrase in your password manager too. Backups cannot be read without it."
pause "Press Enter to go on"

stage "Alerts, Sentry, probe"
ENV_FILE="$CONFIG/company-app-alerts.env"
ask NTFY_URL "ntfy server URL:"
ask NTFY_TOPIC "ntfy topic (a new one, it works like a password):"
ENV_FILE="$CONFIG/company-app-sentry.env"
ask_secret SENTRY_DSN "Sentry DSN (hidden):"
ENV_FILE="$CONFIG/company-app-probe.env"
ask PROBE_USER "Probe user:"
ask_secret PROBE_PASS "Probe password (hidden):"
note "Create that user with tools/perf/seed-probe.sh once the data is in place."
chmod 600 "$CONFIG"/company-app-*.env
pause "Press Enter to go on"

stage "GitHub CLI"
say "The deploy gate reads GitHub runs. Sign in with an account that can read the repo."
gh auth status >/dev/null 2>&1 || gh auth login
pause "Press Enter to go on"

stage "Finish"
say "Run these two, in order:"
say "  tools/replicate/replicate.sh apply"
say "  tools/replicate/replicate.sh check --strict"
say ""
say "To copy data over, stop the app in Coolify, then:"
say "  tools/replicate/restore-latest.sh"
say "It replaces the database and prints the table and user counts."
;;

*)
echo "usage: wizard.sh cloud   before the box exists, from anywhere"
echo "       wizard.sh box     on the new box, after replicate.sh apply stops"
exit 2
;;
esac

finish
}

run_wizard "$@"
